//! `os.lazy.usb.audio.v1` (`idl/usb_audio.midl`, docs/usb-audio-plan.md):
//! the USB audio function `usbd` drives, as `sndd usb=1` talks to it.
//!
//! The stubs and the blocking [`Client`] `sndd`'s USB card uses are
//! generated by `midlc`; this module adds the reply framing `usbd` serves
//! with.

use alloc::vec::Vec;

use libmessenger::{Header, Object, Parcel, VERSION};

use super::client::Native;

/// The generated stubs.
pub use messenger_generated::os_lazy_usb_audio_v1 as wire;

pub use wire::{Device, Progress};

/// The name `usbd` registers while an audio device is bound.
pub const NAME: &str = wire::SERVICE_NAME;

/// The interface id every parcel carries.
pub const INTERFACE: u64 = wire::INTERFACE_ID;

/// A parcel of `method` carrying an encoded `body` and its `objects`
/// (only `Attach` carries one).
pub fn parcel(method: u32, body: Vec<u8>, objects: Vec<Object>) -> Parcel {
    Parcel {
        header: Header {
            version: VERSION,
            flags: 0,
            interface_id: INTERFACE,
            method,
            txn_id: 0,
            reply_to: 0,
            deadline_ns: 0,
        },
        body,
        objects,
    }
}

/// A blocking client of `usbd`'s audio function: `Client::try_connect(Native)`
/// fails with `ENOENT` while no device is bound. Dropping it releases the
/// handle (it was obtained by name, so it is released, not closed).
pub type Client = wire::Client<Native>;

/// Why a call failed (the interface declares no error codes).
pub type ClientError = wire::ClientError;
